class Box
    public define content as integer;
endClass

algorithm CompareObjects
    define flag as integer;
    define a as Box;
    define b as Box;
    read flag;
    a <- new Box();
    if flag = 1 then
        b <- a;
    else
        b <- new Box();
    endIf
    if a = b then
        write 1;
    else
        write 0;
    endIf
endAlgorithm
